import java.util.HashMap;
import java.util.Map;
import java.util.Scanner;

public class Main {
    static Map<String, Integer> all = new HashMap<>();
    static Map<String, Integer> limit = new HashMap<>();
    static int n = 0, m = 0;

    static int searchall(int start, int end) {
        if (start == end) {
            return 1;
        }
        String key = start + "," + end;
        if (all.containsKey(key)) {
            return all.get(key);
        }
        int result = 0;
        result += searchall(start + 1, end);
        result += searchall(start, end - 1);
        for (int i = start + 1; i < end; i++) {
            result += searchall(start, i - 1) * searchall(i + 1, end);
        }
        all.put(key, result);
        return result;
    }

    static int searchlimit(int start, int end, int depth) {
        if (start == end) {
            return (depth < m) ? 1 : 0;
        }
        String key = start + "," + end + "," + depth;
        if (limit.containsKey(key)) {
            return limit.get(key);
        }
        int result = 0;
        result += searchlimit(start + 1, end, depth + 1);
        result += searchlimit(start, end - 1, depth + 1);
        for (int i = start + 1; i < end; i++) {
            result += searchlimit(start, i - 1, depth + 1) * searchlimit(i + 1, end, depth + 1);
        }
        limit.put(key, result);
        return result;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        n = scanner.nextInt();
        m = scanner.nextInt();
        int result = searchall(1, n) - searchlimit(1, n, 1);
        System.out.println(result);
        scanner.close();
    }
}
